<script setup lang="ts">
import { ref,watch,nextTick,onBeforeUnmount } from 'vue'
import { uninstallRequest } from './uninstall'
const clearData=ref(false),frame=ref<HTMLElement>(),previous=ref<HTMLElement>()
function key(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();uninstallRequest.value?.resolve(null)}if(event.key==='Tab'){const nodes=[...frame.value!.querySelectorAll<HTMLElement>('button,input')],index=nodes.indexOf(document.activeElement as HTMLElement);event.preventDefault();nodes[(index+(event.shiftKey?-1:1)+nodes.length)%nodes.length]?.focus()}}
watch(uninstallRequest,async request=>{clearData.value=false;if(request){previous.value=document.activeElement as HTMLElement;window.addEventListener('keydown',key,true);await nextTick();frame.value?.querySelector<HTMLButtonElement>('button')?.focus()}else{window.removeEventListener('keydown',key,true);previous.value?.focus()}})
onBeforeUnmount(()=>{window.removeEventListener('keydown',key,true);uninstallRequest.value?.resolve(null)})
</script>
<template><div v-if="uninstallRequest" class="plugin-uninstall-backdrop"><section ref="frame" class="plugin-uninstall-dialog" role="alertdialog" aria-modal="true" :aria-label="$t('卸载插件')"><h3>{{$t('卸载插件')}} · {{uninstallRequest.name}}</h3><p>{{$t('将删除插件代码并撤销授权，文件不受影响。')}}</p><label><input v-model="clearData" type="checkbox">{{$t('同时删除插件保存的数据，无法恢复')}}</label><footer><button @click="uninstallRequest.resolve(null)">{{$t('取消')}}</button><button @click="uninstallRequest.resolve({clearData})">{{$t('卸载')}}</button></footer></section></div></template>
<style scoped>.plugin-uninstall-backdrop{position:absolute;inset:0;z-index:160;display:grid;place-items:center;background:#0003}.plugin-uninstall-dialog{width:420px;max-width:calc(100% - 32px);padding:22px;border:1px solid var(--line-strong);border-radius:12px;background:var(--paper);color:var(--ink);box-shadow:var(--shadow);font-size:13px;line-height:1.8}.plugin-uninstall-dialog h3{margin:0;font-size:16px}.plugin-uninstall-dialog label{display:flex;gap:8px}.plugin-uninstall-dialog footer{display:flex;gap:10px;justify-content:flex-end;margin-top:18px}.plugin-uninstall-dialog button{padding:6px 15px;border:1px solid var(--line);border-radius:6px;background:var(--panel);color:var(--ink);font:inherit}</style>
